SELECT cs.canonical_smiles, met.substrate_record_id, met.metabolite_record_id, cr_sub.compound_key AS substrate_compound_key, cr_met.compound_key AS metabolite_compound_key, met.met_conversion, met.pathway_key FROM metabolism met JOIN compound_records cr_sub ON cr_sub.record_id = met.substrate_record_id JOIN compound_structures cs ON cs.molregno = cr_sub.molregno LEFT JOIN compound_records cr_met ON cr_met.record_id = met.metabolite_record_id ORDER BY cs.canonical_smiles, met.substrate_record_id, met.metabolite_record_id, cr_sub.compound_key, cr_met.compound_key, met.met_conversion, met.pathway_key LIMIT 200
